'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isNegativeZerof = require( '@stdlib/math/base/assert/is-negative-zerof' );
var isPositiveZerof = require( '@stdlib/math/base/assert/is-positive-zerof' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var isAlmostSameValuef = require( '@stdlib/number/float32/base/assert/is-almost-same-value' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var tryRequire = require( '@stdlib/utils/try-require' );


// FIXTURES //

var small = require( './fixtures/julia/small.json' );
var mediumNegative = require( './fixtures/julia/medium_negative.json' );
var mediumPositive = require( './fixtures/julia/medium_positive.json' );
var largePositive = require( './fixtures/julia/large_positive.json' );
var largerPositive = require( './fixtures/julia/larger_positive.json' );
var hugePositive = require( './fixtures/julia/huge_positive.json' );


// VARIABLES //

var erfinvf = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( erfinvf instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof erfinvf, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided `NaN`, the function returns `NaN`', opts, function test( t ) {
	var y = erfinvf( NaN );
	t.strictEqual( isnanf( y ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided `1`, the function returns `+infinity`', opts, function test( t ) {
	var y = erfinvf( 1.0 );
	t.strictEqual( y, PINF, 'returns expected value' );
	t.end();
});

tape( 'if provided `-1`, the function returns `-infinity`', opts, function test( t ) {
	var y = erfinvf( -1.0 );
	t.strictEqual( y, NINF, 'returns expected value' );
	t.end();
});

tape( 'if provided `-0`, the function returns `-0`', opts, function test( t ) {
	var y = erfinvf( -0.0 );
	t.strictEqual( isNegativeZerof( y ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided `+0`, the function returns `+0`', opts, function test( t ) {
	var y = erfinvf( 0.0 );
	t.strictEqual( isPositiveZerof( y ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided a value which is either less than `-1` or greater than `1`, the function returns `NaN`', opts, function test( t ) {
	var values;
	var y;
	var i;

	values = [
		f32( 3.14 ),
		f32( -3.14 ),
		f32( -1.1 ),
		f32( 1.1 ),
		PINF,
		NINF
	];

	for ( i = 0; i < values.length; i++ ) {
		y = erfinvf( values[ i ] );
		t.strictEqual( isnanf( y ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the inverse error function (small values)', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = small.x;
	expected = small.expected;
	for ( i = 0; i < x.length; i++ ) {
		y = erfinvf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 2 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the inverse error function (medium negative values)', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = mediumNegative.x;
	expected = mediumNegative.expected;
	for ( i = 0; i < x.length; i++ ) {
		y = erfinvf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 2 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the inverse error function (medium positive values)', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = mediumPositive.x;
	expected = mediumPositive.expected;
	for ( i = 0; i < x.length; i++ ) {
		y = erfinvf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 2 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the inverse error function (large positive values)', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = largePositive.x;
	expected = largePositive.expected;
	for ( i = 0; i < x.length; i++ ) {
		y = erfinvf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 3 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the inverse error function (larger positive values)', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = largerPositive.x;
	expected = largerPositive.expected;
	for ( i = 0; i < x.length; i++ ) {
		y = erfinvf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 2 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the inverse error function (huge positive values)', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = hugePositive.x;
	expected = hugePositive.expected;
	for ( i = 0; i < x.length; i++ ) {
		y = erfinvf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 1 ), true, 'returns expected value' );
	}
	t.end();
});
